tool_input.command:
git -C 'D:\repository\数据湖' ls-files -- 分析产出
$dir='D:\repository\数据湖\分析产出'
Get-ChildItem -Path $dir -File | Sort-Object LastWriteTime | ForEach-Object { '{0:MM-dd HH:mm} {1,8:N0} {2}' -f $_.LastWriteTime, $_.Length, $_.Name }

foreach($t in 'CNEquity-SelectionLake-Update','CNEquity-SelectionLake-Audit'){
  "=== $t ==="
  (schtasks /query /tn $t /xml) | Select-String '<Command>','<Arguments>' | ForEach-Object { $_.Line.Trim() }
}

Set-Location 'D:\repository\数据湖\分析产出'
$errs=@(); Get-ChildItem -Filter *.py | ForEach-Object { $o = python -m py_compile $_.Name 2>&1; if($LASTEXITCODE -ne 0){ $errs += "$($_.Name): $o" } }
"compile errors: $($errs.Count)"; $errs
"-- stale refs check --"
Select-String -Path '*.py','*.md' -Pattern 'dps_mode_audit','目标价计算逻辑','口径四方案','口径统一_diff','深市打新底仓专用标准','build_bench','rebuild_sz_md','audit_lake','归档_20261105','_review\.json','成员权重_2026-11-06','替补席_2026-11-06','年度复核结果' | ForEach-Object { "$($_.Filename):$($_.LineNumber):$($_.Line.Trim().Substring(0,[Math]::Min(60,$_.Line.Trim().Length)))" }
